import React from 'react';
import './CaseVisual.css';
import rifleArt from '../assets/cases/type_rifles.png';
import sniperArt from '../assets/cases/type_snipers.png';
import pistolArt from '../assets/cases/type_pistols.png';
import knifeArt from '../assets/cases/type_knives.png';
import glovesArt from '../assets/cases/type_gloves.png';

const THEMES = {
  rifle: { match: ['riflearsenal','fusilarsenal'], title: 'RIFLE ARSENAL', icon: 'AK', accent: '#7f3142', accent2: '#cf6a7f', art: rifleArt },
  sniper: { match: ['sniperarsenal','awparsenal'], title: 'SNIPER ARSENAL', icon: 'AWP', accent: '#2e6688', accent2: '#76b7df', art: sniperArt },
  pistol: { match: ['pistolarsenal'], title: 'PISTOL ARSENAL', icon: 'DE', accent: '#866226', accent2: '#d6ae5a', art: pistolArt },
  knife: { match: ['knifearsenal','knivesarsenal','solidknife'], title: 'KNIFE ARSENAL', icon: '✦', accent: '#8e6a2e', accent2: '#d7bb6f', art: knifeArt },
  gloves: { match: ['glovesarsenal','glovearsenal'], title: 'GLOVES ARSENAL', icon: '✋', accent: '#315f78', accent2: '#75abc2', art: glovesArt },
};

const normalize = (name = '') => String(name)
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]/g, '');

function themeFor(name = '') {
  const n = normalize(name);
  for (const theme of Object.values(THEMES)) {
    if (theme.match.some((token) => n.includes(token))) return theme;
  }
  return null;
}

export function isArsenalCase(name = '') {
  const n = normalize(name);
  return n.includes('arsenalcase') || Boolean(themeFor(name));
}

export default function CaseVisual({ caseData, large = false, splash = false }) {
  const name = caseData?.name || 'WELLCASE CASE';
  const t = themeFor(name) || {
    title: String(name).replace(/\s*case\s*$/i, '').toUpperCase(),
    icon: 'WC', accent: '#556477', accent2: '#94aac4'
  };
  return (
    <div
      data-case-visual={t.title}
      className={`case-visual ${large ? 'case-visual-large' : ''} ${splash ? 'case-visual-splash' : ''}`}
      style={{ '--cv-accent': t.accent, '--cv-accent2': t.accent2, '--cv-glow': `${t.accent2}55` }}
    >
      <div className="cv-stars" />
      <div className="cv-halo" />
      <div className="cv-floor" />
      <div className="cv-crate">
        <div className="cv-lid" />
        <div className="cv-body">
          <div className="cv-corner cv-corner-tl" /><div className="cv-corner cv-corner-tr" />
          <div className="cv-corner cv-corner-bl" /><div className="cv-corner cv-corner-br" />
          <div className="cv-panel"><b>{t.icon}</b><span>WELLCASE</span><em>{t.title}</em>{t.art && <img className="cv-category-art" src={t.art} alt="" aria-hidden="true" />}</div>
          <div className="cv-lock cv-lock-left" /><div className="cv-lock cv-lock-right" />
        </div>
      </div>
      <div className="cv-caption">{t.title}</div>
    </div>
  );
}
